<?php
require_once __DIR__ . '/config/conexion.php';
require_login();
if($_SERVER['REQUEST_METHOD']==='POST'){post_only();$action=$_POST['action']??'';$id=(int)($_POST['id_admin']??0);if($action==='delete'){$count=(int)$pdo->query('SELECT COUNT(*) FROM administradores')->fetchColumn();if($id===(int)$_SESSION['admin_id'])flash('error','No puedes eliminar la cuenta con la que has iniciado sesión.');elseif($count<=1)flash('error','Debe existir al menos un administrador.');else{$pdo->prepare('DELETE FROM administradores WHERE id_admin=?')->execute([$id]);flash('success','Administrador eliminado.');}}elseif($action==='edit'&&$id){$nombre=trim($_POST['nombre']??'');$correo=strtolower(trim($_POST['correo']??''));$password=$_POST['password']??'';if($nombre===''||mb_strlen($nombre)>100||!filter_var($correo,FILTER_VALIDATE_EMAIL)||mb_strlen($correo)>150){flash('error','Ingresa un nombre y correo válidos.');}else{try{if($password!==''){if(strlen($password)<8)throw new RuntimeException('La contraseña requiere al menos 8 caracteres.');$pdo->prepare('UPDATE administradores SET nombre=?,correo=?,password_hash=? WHERE id_admin=?')->execute([$nombre,$correo,password_hash($password,PASSWORD_DEFAULT),$id]);}else{$pdo->prepare('UPDATE administradores SET nombre=?,correo=? WHERE id_admin=?')->execute([$nombre,$correo,$id]);}if($id===(int)$_SESSION['admin_id'])$_SESSION['admin_name']=$nombre;flash('success','Administrador actualizado.');}catch(Throwable $ex){flash('error',$ex instanceof RuntimeException?$ex->getMessage():'Ese correo ya está registrado.');}}}header('Location: admins.php');exit;}
$admins=$pdo->query('SELECT id_admin,nombre,correo,creado_en FROM administradores ORDER BY id_admin')->fetchAll();$edit=null;if(isset($_GET['editar'])){$s=$pdo->prepare('SELECT id_admin,nombre,correo FROM administradores WHERE id_admin=?');$s->execute([(int)$_GET['editar']]);$edit=$s->fetch();}page_start('Administradores','admins.php');
?>
<div class="page-heading"><div><span class="eyebrow">ACCESO</span><h1>Administradores</h1><p>Gestiona las cuentas que pueden iniciar sesión.</p></div><a class="btn btn-primary" href="register.php">Registrar administrador</a></div>
<?php if($edit): ?><section class="panel mb-4"><h2>Editar administrador</h2><form method="post" class="row g-3"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()); ?>"><input type="hidden" name="action" value="edit"><input type="hidden" name="id_admin" value="<?= (int)$edit['id_admin']; ?>"><div class="col-md-4"><label class="form-label">Nombre</label><input class="form-control" name="nombre" maxlength="100" required value="<?= e($edit['nombre']); ?>"></div><div class="col-md-4"><label class="form-label">Correo</label><input class="form-control" type="email" name="correo" maxlength="150" required value="<?= e($edit['correo']); ?>"></div><div class="col-md-4"><label class="form-label">Nueva contraseña (opcional)</label><input class="form-control" type="password" name="password" minlength="8" autocomplete="new-password"></div><div class="col-12"><button class="btn btn-primary">Guardar</button> <a class="btn btn-outline-secondary" href="admins.php">Cancelar</a></div></form></section><?php endif; ?>
<section class="panel"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Nombre</th><th>Correo</th><th>Creado</th><th>Acciones</th></tr></thead><tbody><?php foreach($admins as $a): ?><tr><td><?= e($a['nombre']); ?> <?= (int)$a['id_admin']===(int)$_SESSION['admin_id']?'<span class="badge text-bg-primary">Tú</span>':''; ?></td><td><?= e($a['correo']); ?></td><td><?= e($a['creado_en']); ?></td><td class="d-flex gap-2"><a class="btn btn-sm btn-outline-primary" href="admins.php?editar=<?= (int)$a['id_admin']; ?>">Editar</a><?php if((int)$a['id_admin']!==(int)$_SESSION['admin_id']): ?><form method="post" onsubmit="return confirm('¿Eliminar este administrador?')"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()); ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id_admin" value="<?= (int)$a['id_admin']; ?>"><button class="btn btn-sm btn-outline-danger">Eliminar</button></form><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php page_end(); ?>
